  rows.sort((a,b)=>a.start-b.start);let current=null;
  const flush=()=>{if(!current)return;const length=current.end-current.start,center=(current.start+current.end)/2;out.push({...current.w,id:'r55:joined-wall:'+id+':'+n++,x:current.alongX?center:current.w.x,y:current.alongX?current.w.y:center,width:current.alongX?length:current.w.width,depth:current.alongX?current.w.depth:length,regionalVisual55:true});};
